'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const force = Number(input[1]);
const grid = input.slice(2, 2 + n).map(row => row.split(''));

if (Number(grid[0][0]) <= force) {
  const visited = new Uint8Array(n * n);
  const queue = new Int32Array(n * n);
  let head = 0;
  let tail = 0;

  visited[0] = 1;
  grid[0][0] = '*';
  queue[tail++] = 0;

  while (head < tail) {
    const pos = queue[head++];
    const r = Math.floor(pos / n);
    const c = pos % n;

    const neighbors = [
      r > 0 ? pos - n : -1,
      r + 1 < n ? pos + n : -1,
      c > 0 ? pos - 1 : -1,
      c + 1 < n ? pos + 1 : -1
    ];

    for (const next of neighbors) {
      if (next === -1 || visited[next]) continue;

      const nr = Math.floor(next / n);
      const nc = next % n;
      if (Number(grid[nr][nc]) <= force) {
        visited[next] = 1;
        grid[nr][nc] = '*';
        queue[tail++] = next;
      }
    }
  }
}

process.stdout.write(grid.map(row => row.join('')).join('\n'));
